"use client";

import { useEffect, useId, useRef, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
	Dialog,
	DialogContent,
	DialogDescription,
	DialogHeader,
	DialogTitle,
	DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { CreditCardIcon, StoreIcon } from "lucide-react";
import { usePaymentInputs } from "react-payment-inputs";
import images, { type CardImages } from "react-payment-inputs/images";

export default function Component() {
	const id = useId();
	const {
		meta,
		getCardNumberProps,
		getExpiryDateProps,
		getCVCProps,
		getCardImageProps,
	} = usePaymentInputs();
	const couponInputRef = useRef<HTMLInputElement>(null);
	const [showCouponInput, setShowCouponInput] = useState(false);
	const [couponCode, setCouponCode] = useState("");

	// Auto-focus the coupon input when it's shown
	useEffect(() => {
		if (showCouponInput && couponInputRef.current) {
			couponInputRef.current.focus();
		}
	}, [showCouponInput]);

	return (
		<Dialog>
			<DialogTrigger asChild>
				<Button variant="outline">Checkout</Button>
			</DialogTrigger>
			<DialogContent>
				<div className="mb-2 flex flex-col gap-2">
					<div
						className="flex size-11 shrink-0 items-center justify-center rounded-full border"
						aria-hidden="true"
					>
						<StoreIcon className="opacity-80" size={16} />
					</div>
					<DialogHeader>
						<DialogTitle className="text-left">
							Confirm and pay
						</DialogTitle>
						<DialogDescription className="text-left">
							Pay securely and cancel any time.
						</DialogDescription>
					</DialogHeader>
				</div>

				<form className="space-y-5">
					<div className="space-y-4">
						<RadioGroup className="grid-cols-2" defaultValue="yearly">
							{/* Monthly */}
							<label className="border-input has-data-[state=checked]:border-primary/50 has-focus-visible:border-ring has-focus-visible:ring-ring/50 relative flex cursor-pointer flex-col gap-1 rounded-md border px-4 py-3 shadow-2xs transition-[color,box-shadow] outline-hidden has-focus-visible:ring-[3px]">
								<RadioGroupItem
									id="radio-monthly"
									value="monthly"
									className="sr-only after:absolute after:inset-0"
								/>
								<p className="text-foreground text-sm font-medium">
									Monthly
								</p>
								<p className="text-muted-foreground text-sm">
									$32/month
								</p>
							</label>
							{/* Yearly */}
							<label className="border-input has-data-[state=checked]:border-primary/50 has-focus-visible:border-ring has-focus-visible:ring-ring/50 relative flex cursor-pointer flex-col gap-1 rounded-md border px-4 py-3 shadow-2xs transition-[color,box-shadow] outline-hidden has-focus-visible:ring-[3px]">
								<RadioGroupItem
									id="radio-yearly"
									value="yearly"
									className="sr-only after:absolute after:inset-0"
								/>
								<div className="inline-flex items-start justify-between gap-2">
									<p className="text-foreground text-sm font-medium">
										Yearly
									</p>
									<Badge>Popular</Badge>
								</div>
								<p className="text-muted-foreground text-sm">
									$320/month
								</p>
							</label>
						</RadioGroup>
						<div className="not-first:*:mt-2">
							<Label htmlFor={`name-${id}`}>Name on card</Label>
							<Input id={`name-${id}`} type="text" required />
						</div>
						<div className="not-first:*:mt-2">
							<legend className="text-foreground text-sm font-medium">
								Card Details
							</legend>
							<div className="rounded-md shadow-2xs">
								<div className="relative focus-within:z-10">
									<Input
										className="peer rounded-b-none pe-9 shadow-none [direction:inherit]"
										{...getCardNumberProps()}
									/>
									<div className="text-muted-foreground/80 pointer-events-none absolute inset-y-0 inset-e-0 flex items-center justify-center pe-3 peer-disabled:opacity-50">
										{meta.cardType ? (
											<svg
												className="overflow-hidden rounded-sm"
												{...getCardImageProps({
													images: images as unknown as CardImages,
												})}
												width={20}
											/>
										) : (
											<CreditCardIcon size={16} aria-hidden="true" />
										)}
									</div>
								</div>
								<div className="-mt-px flex">
									<div className="min-w-0 flex-1 focus-within:z-10">
										<Input
											className="rounded-e-none rounded-t-none shadow-none [direction:inherit]"
											{...getExpiryDateProps()}
										/>
									</div>
									<div className="-ms-px min-w-0 flex-1 focus-within:z-10">
										<Input
											className="rounded-s-none rounded-t-none shadow-none [direction:inherit]"
											{...getCVCProps()}
										/>
									</div>
								</div>
							</div>
						</div>
						{!showCouponInput ? (
							<button
								type="button"
								onClick={() => setShowCouponInput(true)}
								className="text-sm underline hover:no-underline"
							>
								+ Add coupon
							</button>
						) : (
							<div className="not-first:*:mt-2">
								<Label htmlFor={`coupon-${id}`}>Coupon code</Label>
								<Input
									id={`coupon-${id}`}
									ref={couponInputRef}
									placeholder="Enter your code"
									value={couponCode}
									onChange={(e) => setCouponCode(e.target.value)}
								/>
							</div>
						)}
					</div>
					<Button type="button" className="w-full">
						Subscribe
					</Button>
				</form>

				<p className="text-muted-foreground text-center text-xs">
					Payments are non-refundable. Cancel anytime.
				</p>
			</DialogContent>
		</Dialog>
	);
}

import React from "react";

import { cn } from "@/lib/utils";
import { cva, type VariantProps } from "class-variance-authority";

const badgeVariants = cva(
	"inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-hidden focus:ring-2 focus:ring-ring focus:ring-offset-2",
	{
		variants: {
			variant: {
				default:
					"border-transparent bg-primary text-primary-foreground hover:bg-primary/80",
				secondary:
					"border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
				destructive:
					"border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
				outline: "text-foreground",
			},
		},
		defaultVariants: {
			variant: "default",
		},
	}
);

export interface BadgeProps
	extends React.HTMLAttributes<HTMLDivElement>,
		VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
	return (
		<div className={cn(badgeVariants({ variant }), className)} {...props} />
	);
}

export { Badge, badgeVariants };

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

